# Développement en prose après chaque schéma et tableau, groupe a du chapitre 1.
ADD = {}

def P(*ts): return [{"type": "p", "text": t} for t in ts]
def Q(objection, reponse, suite=None):
    d = {"type": "objection", "objection": objection, "reponse": reponse}
    if suite: d["suite"] = suite
    return d
def dev(paras, *objs): return P(*paras) + list(objs)

# ---------------------------------------------------------------- Allāh
ADD["« Allāh » est le nom, en arabe, de Celui qui crée toute chose"] = {"after": {
"Nom figé ou nom dérivé ?": dev([
  "Prenons ce tableau ligne par ligne. **Première ligne, la thèse** : pour le premier groupe de savants, « Allāh » est un nom propre posé tel quel, comme un prénom qu'on donne sans l'expliquer ; pour le second, il vient du mot « ilāh », « divinité », auquel on a ajouté l'article, « al-ilāh », puis la prononciation s'est contractée en « Allāh ».",
  "**Deuxième ligne, les savants** : on voit que les deux avis sont portés par de très grands noms, al-Shāfiʿī, al-Ghazālī et al-Khattābī d'un côté, al-Kisāʾī et al-Farrāʾ de l'autre, et que même al-Khalīl et Sībawayh, les pères de la grammaire arabe, sont cités dans les deux camps selon les transmissions. Ce n'est donc pas un débat entre savants sérieux et amateurs.",
  "**Troisième ligne, l'argument** : le premier groupe s'appuie sur un fait de langue très simple, que chacun peut vérifier. En arabe, on n'appelle jamais quelqu'un en gardant l'article : on ne dit pas « Yā al-Rahmān ». Or on dit « Yā Allāh ». L'article fait donc partie du nom lui-même. Le second groupe répond que le mot « taʾalluh », « dévotion », existe bel et bien dans la langue ancienne, ce qui montre que la racine était vivante.",
  "**Quatrième ligne, ce qu'ils partagent** : c'est la plus importante. Quel que soit l'avis retenu, le nom désigne **le seul Dieu véritable**. Le débat porte sur l'histoire du mot, jamais sur l'identité de Celui qu'il nomme."],
  Q("Si les savants ne sont pas d'accord sur l'origine du mot, comment être sûr de ce qu'il veut dire ?",
    "Parce que le sens d'un nom ne dépend pas de son étymologie, mais de son usage. Nous ne savons pas toujours d'où viennent nos propres prénoms, et nous savons parfaitement qui ils désignent. Ibn al-Qayyim l'a dit : tous les habitants de la terre, savants et ignorants, savent qu'« Allāh » est le nom du Seigneur des mondes.",
    "Le débat étymologique enrichit la méditation ; il ne met jamais en doute la référence.")),
"Les sens proposés pour la racine": dev([
  "Ce schéma présente quatre sens qu'on a proposés pour la racine du mot, si l'on suit l'avis de ceux qui le disent dérivé. Il ne faut pas les lire comme quatre hypothèses concurrentes, mais comme **quatre facettes d'une même relation**.",
  "**Adorer** : c'est le sens le plus direct. « Ilāh », c'est celui qu'on adore ; « lā ilāha illā Allāh » signifie donc qu'aucune adoration n'est légitime sauf envers Lui. **Se tourner vers Lui dans le besoin** : al-Dahhāk explique que les créatures se tournent vers Lui dans leurs détresses ; le mot dit donc aussi notre dépendance. **Rester interdit de stupeur** : l'intelligence, quand elle essaie de saisir Sa réalité, s'arrête, éblouie ; le nom contient l'aveu de notre limite. **Trouver l'apaisement** : le cœur ne trouve le repos qu'en Lui, comme le dit le verset « c'est par le rappel d'Allāh que les cœurs se tranquillisent » (13:28).",
  "Ces quatre sens forment un chemin intérieur : je L'adore, parce que j'ai besoin de Lui ; je ne Le comprends pas entièrement, et pourtant c'est en Lui que je trouve la paix. **Tout le rapport du croyant à Dieu est déjà contenu dans le nom.**"],
  Q("N'est-ce pas trop demander à un seul mot ?",
    "Ce n'est pas le mot qui contient tout cela par magie ; ce sont les savants qui ont observé les emplois de la racine dans la langue arabe, et qui ont constaté qu'ils renvoient tous à cette même relation. La légende du schéma le dit : tous ces sens convergent vers Celui vers qui se tournent l'adoration, le besoin et le cœur.")),
"Ce que « al-Samad » produit dans le cœur": dev([
  "Ce cycle se lit comme une boucle qui se renforce elle-même. **Il se suffit à Lui-même** : je n'ai rien à Lui apporter, et cela me libère de l'idée que ma prière Lui serait utile. **Tout dépend de Lui** : chaque besoin, même minuscule, trouve donc en Lui son adresse. **Il demeure** : tout ce à quoi je m'attache passera, Lui reste. **Je me tourne vers Lui** : l'invocation devient le premier réflexe, et non le dernier recours quand tout a échoué.",
  "Et la boucle repart : plus je me tourne vers Lui, plus je constate qu'Il se suffit et que tout dépend de Lui. Ce n'est pas une théorie sur Dieu ; c'est **une habitude du cœur** qui se construit."],
  Q("Si Dieu n'a besoin de rien, pourquoi me demande-t-Il de L'invoquer ?",
    "Justement parce que c'est moi qui en ai besoin. Ibn al-Mubārak disait qu'al-Rahīm « se fâche quand on ne Lui demande pas » : non par manque, mais parce que celui qui ne demande pas se coupe de la source. L'invocation ne nourrit pas Dieu ; elle me relie à ce qui me nourrit.")),
"Une subtilité relevée par les savants": dev([
  "Cette observation est une curiosité de la langue, et le schéma le précise honnêtement : **une beauté, non une preuve**. Si l'on retire la première lettre du mot « الله », on obtient « لله », « à Allāh » ; si l'on en retire encore une, « له », « à Lui » ; et enfin « هو », « Lui ». À chaque étape, le mot garde un sens qui renvoie à Dieu, et le Coran emploie chacune de ces formes.",
  "Pourquoi le mentionner ? Parce que cela illustre une idée vraie par ailleurs : le nom « Allāh » ne se déforme pas, ne se met pas au pluriel, n'a pas de féminin. Il a dans la langue un statut à part, comme Celui qu'il désigne a dans l'existence un statut à part."],
  Q("Ne risque-t-on pas de tomber dans des spéculations sur les lettres ?",
    "Si, et c'est pour cela que la légende précise que ce n'est pas une preuve de croyance. On peut admirer une harmonie de la langue sans en faire un fondement. La foi repose sur le Coran et la Sunna, pas sur des jeux de lettres.")),
"Allāh et ilāh : deux mots, deux réalités": dev([
  "Ce tableau est la clé de l'attestation de foi. **« Ilāh »** est un nom commun : il désigne tout ce qui est adoré, que cette adoration soit juste ou fausse. On peut donc dire « des ilāhs » au pluriel, et le Coran parle des divinités des polythéistes. **« Allāh »** est un nom propre : il ne désigne qu'un seul être, et n'a ni pluriel ni duel.",
  "Regarde maintenant la dernière ligne : la shahāda commence par **« lā ilāha »**, « il n'y a pas de divinité », c'est-à-dire qu'elle nie toutes les divinités possibles, avec le nom commun ; puis elle termine par **« illā Allāh »**, « sauf Allāh », avec le nom propre. On vide d'abord la place, puis on la donne à Celui qui seul la mérite.",
  "C'est pour cela que la shahāda n'est pas une simple affirmation de l'existence de Dieu : même les polythéistes de La Mecque reconnaissaient Allāh. Elle est **une négation de tout autre objet d'adoration**."],
  Q("Pourquoi ne pas simplement dire « Allāh existe » ?",
    "Parce que ce n'était pas la question. Les Mecquois croyaient en Allāh comme Créateur, mais adoraient d'autres divinités à côté de Lui. La shahāda vise précisément cela : elle ne demande pas seulement de reconnaître Dieu, mais de cesser d'adorer quoi que ce soit d'autre.")),
"Le nom « Allāh » au quotidien": dev([
  "Ce cycle transforme chaque sens de la racine en attitude concrète. **Je L'adore** : c'est le sens d'« ilāh », Celui qui est adoré. **Je me tourne vers Lui** : c'est le sens d'« aliha ilayhi », se tourner vers quelqu'un dans le besoin. **Je L'invoque par Ses noms** : c'est l'ordre de 7:180. **Mon cœur s'apaise** : c'est le sens de l'apaisement et le verset 13:28.",
  "Ainsi, prononcer « Allāh » dans la journée n'est pas une formule vide : chaque fois, c'est **un rappel de ces quatre attitudes**. Celui qui dit « bismillāh » avant de manger, « in shāʾ Allāh » avant de promettre, « al-hamdu lillāh » après un bienfait, refait ce cycle des dizaines de fois par jour."])
}}

# ---------------------------------------------------------------- Fitra
ADD["Croire en Dieu est naturel à l'homme"] = {"after": {
"La fitra comparée à la capacité de parler": dev([
  "Reprenons la comparaison ligne par ligne, car elle répond à presque toutes les objections. **À la naissance** : un bébé ne parle pas, et pourtant personne ne doute qu'il ait la capacité de parler. De même, un nouveau-né ne prononce pas « lā ilāha illā Allāh », et pourtant il porte l'orientation qui le rendra capable de reconnaître son Créateur. C'est exactement l'argument d'Ibn ʿAbd al-Barr : la fitra n'est pas l'islam pratiqué, c'est une aptitude.",
  "**Ce que donne le milieu** : l'enfant parlera arabe s'il grandit à Damas, français s'il grandit à Lyon. Le hadith dit la même chose de la croyance : « ce sont ses parents qui en font un juif, un chrétien ou un mazdéen ». Le milieu donne **la forme**, il ne crée pas **la capacité**.",
  "**Si le milieu est absent ou hostile** : un enfant privé de langage parlera mal, mais il ne perd pas son cerveau de locuteur. De même, celui qui a grandi sans aucune référence à Dieu n'a pas perdu sa fitra : elle est recouverte, en sommeil. **Ce qui la réveille** : pour la langue, le contact avec des locuteurs ; pour la fitra, le rappel, la réflexion, et souvent la détresse, comme dans le verset du bateau (29:65).",
  "**La conclusion** découle d'elle-même : on dit que le langage est naturel et que les langues sont apprises ; on doit dire de même que **la recherche de Dieu est naturelle**, et que **le contenu exact de la foi est révélé**. C'est pour cela que la fitra a besoin des messagers : elle oriente, la révélation précise."],
  Q("Si la fitra existe, pourquoi a-t-on besoin des prophètes ?",
    "Parce qu'une orientation ne suffit pas à connaître le détail. La fitra me pousse à chercher un Créateur unique ; elle ne me dit pas comment Il veut être adoré, ce qui m'attend après la mort, ni ce qu'Il a ordonné. Al-Shinqītī souligne que Dieu a dit « jusqu'à ce que Nous envoyions un messager », et non « jusqu'à ce que Nous déposions une fitra » : la fitra prépare, le messager accomplit.",
    "La fitra est comme la soif ; la révélation est l'eau. La soif prouve que l'eau existe, mais elle ne remplace pas l'eau."),
  Q("Les langues varient énormément ; les religions aussi. Cela ne prouve-t-il pas que tout est culturel ?",
    "La variété des langues ne prouve pas que le langage soit une invention arbitraire : elle prouve au contraire qu'une même capacité s'exprime partout. De même, la présence d'une croyance en un ou plusieurs êtres supérieurs dans presque toutes les cultures connues est un indice de la fitra, et non une preuve contre elle. La révélation vient ensuite corriger les formes déviées.")),
"Ce qui se passe entre la naissance et l'âge adulte": dev([
  "Ce schéma raconte la vie d'une fitra en cinq étapes. **À la naissance**, elle est intacte, comme le petit animal « entier » du hadith. **L'éducation** lui donne une forme : des parents qui parlent de Dieu avec amour la confirment, d'autres la dévient, d'autres encore la laissent en friche. **Les distractions** viennent ensuite : les désirs, l'agitation, les suggestions du démon, que le hadith de ʿIyād ibn Himār décrit comme un détournement.",
  "Puis arrivent **les moments de vérité** : la maladie, la mort d'un proche, un danger, ou au contraire la contemplation d'une beauté bouleversante. Dans ces moments, la fitra remonte à la surface, même chez celui qui n'y pensait jamais. C'est ce que montre le verset des gens en bateau, qui invoquent Dieu sincèrement dans la tempête.",
  "Enfin vient **le choix adulte**. Le schéma ne s'arrête pas sur une fatalité : chacun, après avoir entendu le rappel, décide de suivre son orientation première ou de la refuser. **La fitra n'est pas un destin, c'est une invitation.**"],
  Q("Et si mon éducation m'a éloigné de Dieu, suis-je responsable ?",
    "Tu n'es pas responsable de ton éducation, mais tu es responsable de ce que tu fais une fois le rappel entendu. C'est exactement la logique du verset 17:15 et du commentaire d'al-Shinqītī : Dieu ne juge personne avant que l'avertissement lui soit parvenu. Le fait que tu te poses aujourd'hui la question signifie que le rappel est en train de te parvenir.")),
"Les trois étages de la fitra selon Ibn ʿĀshūr": dev([
  "Ce schéma est l'apport le plus original d'Ibn ʿĀshūr. Il part de ce que tout le monde admet, **la fitra du corps** : personne ne nous apprend à marcher debout ou à saisir les objets avec les mains, c'est ainsi que nous sommes faits. Il monte ensuite à **la fitra de l'intelligence** : chercher une cause à tout effet, tirer une conclusion de ses prémisses, tenir le monde pour réel. Personne non plus ne nous l'apprend ; celui qui le nie, comme les sophistes, va contre sa propre nature.",
  "Le troisième étage, **la fitra de la religion**, n'est pas une faculté supplémentaire mystérieuse : c'est **la même intelligence appliquée au monde entier**. Si tout effet a une cause, le monde a une cause ; et si cette cause doit expliquer l'ordre de l'ensemble, elle est une et suffisante. C'est pourquoi Ibn ʿĀshūr dit que l'homme laissé à sa réflexion, sans qu'on lui inculque une croyance égarée, parviendrait au monothéisme.",
  "Le quatrième nœud, **la loi**, ajoute que les règles de l'islam ne contredisent jamais cette nature : elles la confirment, ou elles sont faites pour son bien. C'est pour cela, dit-il, que l'islam est une religion « facile et tolérante » : il ne demande pas à l'homme de devenir autre chose que ce qu'il est."],
  Q("Mais de grands esprits ont raisonné et ne sont pas arrivés au monothéisme. La raison suffit-elle vraiment ?",
    "Ibn ʿĀshūr précise lui-même, en citant Ibn Sīnā, que beaucoup de choses nous semblent évidentes simplement par habitude, et que la fitra peut être recouverte par des croyances reçues. La raison pure conduit au tawhīd ; mais la raison réelle des hommes est rarement pure : elle est chargée d'habitudes, de passions et d'intérêts. C'est pourquoi il faut à la fois la réflexion et le rappel.")),
"Ce que montre l'image du hadith": dev([
  "Cette image est d'une grande force pédagogique, parce que tout Arabe de l'époque la comprenait immédiatement. Les éleveurs avaient l'habitude de couper l'oreille de certaines bêtes, par superstition ou pour les marquer. Le Prophète ﷺ demande : avez-vous déjà vu **un agneau naître avec l'oreille coupée** ? Jamais. La mutilation est toujours faite après, par une main extérieure.",
  "Le tableau applique cela à l'homme ligne par ligne. **À la naissance**, l'enfant est « entier » (jamʿāʾ), orienté vers son Créateur. **Ce qui arrive ensuite** : le milieu inculque une croyance déviée, comme l'éleveur coupe l'oreille. **D'où vient le défaut** : de l'extérieur, jamais de la création. **Ce que cela prouve** : l'égarement n'est pas la nature de l'homme ; c'est une blessure qu'on lui a faite."],
  Q("Cela veut-il dire que les parents non musulmans « mutilent » leurs enfants ?",
    "Le hadith décrit un mécanisme, pas une accusation. Les parents transmettent ce qu'ils ont eux-mêmes reçu, souvent avec un amour sincère. L'image dit seulement que la déviation vient de l'extérieur, et donc qu'elle n'est pas irréversible : ce qu'une main a fait, une autre main, celle du rappel, peut le soigner.")),
"« Lā tabdīla li-khalqi llāh »": dev([
  "Ce tableau présente deux lectures d'une seule phrase coranique, et il faut voir qu'elles **ne s'excluent pas**. **Comme un ordre** : « ne changez pas la création d'Allāh ». La phrase est alors une mise en garde adressée à ceux qui éduquent : ne déformez pas la fitra de ceux qui vous sont confiés. Ibn Kathīr juge ce sens « beau et correct ».",
  "**Comme une information** : « la création d'Allāh ne change pas ». La phrase dit alors que Dieu a créé **tous** les hommes sur la même fitra, sans exception ni inégalité. C'est le sens que retiennent Ibn ʿAbbās, Mujāhid, ʿIkrima et Qatāda, pour qui « la création d'Allāh » veut dire « la religion d'Allāh ».",
  "Ensemble, les deux lectures donnent une responsabilité et une espérance : **une responsabilité**, celle de protéger la fitra des autres ; **une espérance**, celle de savoir que la fitra de chacun, même recouverte, n'a jamais été remplacée par autre chose."],
  Q("Si la création ne change pas, comment des gens peuvent-ils devenir mécréants ?",
    "La seconde lecture ne dit pas que personne ne dévie ; elle dit que la constitution d'origine n'est pas remplacée. La fitra peut être recouverte, ignorée, contredite par les actes ; elle n'est pas détruite. C'est pourquoi un homme qui a vécu des décennies loin de Dieu peut, un jour, Le retrouver comme s'il revenait chez lui.")),
"Le cycle que décrit le Coran": dev([
  "Ce schéma décrit un cycle que chacun peut observer autour de soi, et souvent en soi-même. **Le confort** : tant que tout va bien, les appuis humains, l'argent, la santé, les relations, masquent notre dépendance ; on oublie Dieu sans même l'avoir décidé. **La détresse** : un danger survient, les appuis tombent ; il ne reste qu'un seul recours, et l'homme se tourne vers Lui, sincèrement, comme les gens du bateau.",
  "**Le salut** : Dieu répond, même à celui dont Il sait qu'il L'oubliera ensuite. C'est une preuve de Sa générosité. **Le choix** : une fois revenu sur la terre ferme, soit l'oubli revient, et l'on attribue le salut au capitaine ou à la chance, soit l'on tire la leçon pour toujours, comme ʿIkrima ibn Abī Jahl.",
  "Le Coran ne raconte pas ce cycle pour nous juger, mais pour nous **prévenir** : ce qui t'a sauvé dans la tempête est le même qui te fait vivre dans le calme. **Ne L'oublie pas quand la mer est calme.**"],
  Q("Invoquer Dieu seulement dans le danger, n'est-ce pas de l'hypocrisie ?",
    "C'est une faiblesse humaine que le Coran constate, et non une preuve que Dieu n'existe pas. Au contraire, le fait que même celui qui L'oubliait se tourne spontanément vers Lui dans la détresse montre que l'orientation était là. Le reproche du Coran porte sur l'oubli qui suit, pas sur l'appel au secours.")),
"Les voiles sur la fitra, et leurs remèdes": dev([
  "Ce tableau est conçu comme un diagnostic, avec pour chaque mal son remède. **L'héritage** : on croit ce qu'on a reçu sans l'examiner. Le remède est de faire ce que le Coran demande aux polythéistes eux-mêmes : « apportez votre preuve », c'est-à-dire **examiner par soi-même**. **Les suggestions** : le hadith dit que les démons ont détourné les hommes ; le remède est le rappel de Dieu et la recherche de Sa protection.",
  "**Le confort** : l'aisance endort la conscience de notre dépendance ; le remède est de **se souvenir des moments de détresse passés** et de cultiver la gratitude, qui est une manière de garder Dieu présent dans le calme. **L'habitude déguisée en évidence** : ce qu'on a toujours entendu paraît naturel ; le remède est l'expérience de pensée d'Ibn Sīnā, qui consiste à distinguer ce qui résiste réellement au doute de ce qui est seulement familier.",
  "On remarque que **chaque remède est à la portée de chacun** : aucun ne demande d'être savant. C'est une conséquence directe de la fitra : puisqu'elle est en tous, le chemin du retour est ouvert à tous."]),
"Trois lectures du mot « fitra »": dev([
  "Ce tableau montre que les savants n'ont pas tous défini la fitra de la même façon, et que chaque définition éclaire un aspect. **L'islam lui-même** : pour Abū Hurayra et al-Zuhrī, l'enfant naît sur la religion d'islam. C'est la lecture la plus directe du hadith. **Le pacte primordial** : pour Ishāq ibn Rāhawayh et Hammād ibn Salama, la fitra est la reconnaissance que les âmes ont donnée à Dieu avant même la naissance (7:172). **Ce que Dieu a commencé pour lui** : pour Ibn al-Mubārak, la fitra inclut à la fois la disposition au bien et ce que Dieu a décrété pour chacun.",
  "Ibn ʿAbd al-Barr, qui rapporte ces avis, fait une objection décisive à la première lecture prise au sens strict : l'islam est parole, conviction et œuvre ; un nouveau-né n'a rien de cela. La fitra est donc **une aptitude qui conduit à l'islam**, pas l'islam déjà accompli. Et il note que l'arrangement du Muwatta, où Mālik place ce hadith dans le chapitre du décret, indique que l'imam penchait vers la troisième lecture."],
  Q("Alors, laquelle est la bonne ?",
    "Elles se complètent plus qu'elles ne s'opposent. L'enfant naît orienté vers l'islam (première lecture), parce qu'il porte la trace de la reconnaissance primordiale (deuxième lecture), et cela fait partie de ce que Dieu a décrété pour lui (troisième lecture). Ibn ʿAbd al-Barr refuse seulement qu'on dise que le bébé est déjà « musulman » au sens juridique, avec les obligations que cela implique.")),
"De la fitra au détournement, et retour": dev([
  "Ce schéma réunit les deux hadiths en une seule histoire. **La création droite** : Dieu a créé Ses serviteurs « hunafāʾ », c'est-à-dire, selon Ibn ʿAbd al-Barr, monothéistes, refusant l'association. **Le milieu** : les parents donnent une forme à ce qui a été reçu. **Le détournement** : les démons viennent et font dévier les hommes, comme on égare un voyageur de sa route ; le mot arabe « ijtiyāl » contient cette idée de faire tourner quelqu'un en rond.",
  "Le dernier nœud est le plus important : **le rappel**. La révélation ne crée pas la fitra ; elle l'**époussette**. C'est pour cela que le Coran s'appelle lui-même « al-Dhikr », le Rappel : il ne nous apprend pas quelque chose de totalement étranger, il nous **rappelle** ce que nous savions déjà au fond."],
  Q("Si les démons détournent les hommes, ceux-ci sont-ils encore responsables ?",
    "Oui, car le démon n'a qu'un pouvoir de suggestion, pas de contrainte. Le Coran rapporte qu'il dira lui-même au Jour dernier : « je n'avais sur vous aucun pouvoir, sinon que je vous ai appelés et que vous m'avez répondu ; ne me blâmez pas, blâmez-vous vous-mêmes » (14:22). Le détournement est une tentation, non une fatalité.")),
"La fitra chez les savants": dev([
  "Ce tableau récapitulatif montre une chose frappante : sur plus de mille ans, du Compagnon Abū Hurayra jusqu'à Ibn ʿĀshūr au vingtième siècle, **les savants affirment tous la même idée de fond**, même s'ils la formulent différemment. L'homme est créé orienté vers son Créateur ; cette orientation peut être recouverte ; le tawhīd est la fitra, et l'association en est une altération.",
  "Les nuances entre eux, que nous avons vues tout au long de la page, ne portent que sur la manière de décrire cette orientation : islam au sens large, pacte primordial, aptitude, constitution intellectuelle. Ce consensus de fond, à travers les siècles et les régions, est en lui-même une confirmation de la solidité de l'idée."])
}}

# ---------------------------------------------------------------- Savants
ADD["Si la foi est rationnelle, pourquoi tant de savants n'y adhèrent-ils pas ?"] = {"after": {
"Les trois étapes de l'adhésion": dev([
  "Ce schéma décompose ce qu'on appelle « croire » en trois étapes distinctes, et c'est en les distinguant que la question se résout. **Savoir** : comprendre les preuves. Un grand physicien peut connaître parfaitement l'ordre de l'univers, ses lois, son réglage fin. Sur ce point, il en sait souvent plus que le croyant moyen.",
  "**Vouloir regarder** : accepter de poser la question du sens, et pas seulement celle du fonctionnement. Beaucoup de savants s'interdisent méthodiquement cette question dans leur travail, ce qui est légitime pour la science, mais finissent par se l'interdire aussi dans leur vie. On peut passer toute une existence à étudier une lettre sans jamais se demander qui l'a écrite.",
  "**Consentir** : accepter ce que la vérité implique. C'est l'étape la plus coûteuse, car reconnaître un Créateur, c'est reconnaître un Maître, des obligations, des interdits, un jugement. Le dernier nœud du schéma nomme ce qui bloque le plus souvent : l'orgueil et l'intérêt. Le Coran le dit de Pharaon et de ses notables : **ils avaient la certitude, et ils ont nié** (27:14)."],
  Q("N'est-ce pas un procès d'intention envers les savants athées ?",
    "Il ne s'agit pas de juger les intentions de telle ou telle personne : Dieu seul connaît les cœurs. Il s'agit de montrer que l'argument « les savants ne croient pas, donc la foi est irrationnelle » est faible, parce que la foi ne dépend pas seulement de l'intelligence. Un savant peut ne pas croire pour mille raisons, dont certaines sont honnêtes ; mais cela ne prouve rien contre les preuves elles-mêmes."),
  Q("Et si un savant a vraiment examiné les preuves et ne les trouve pas convaincantes ?",
    "Alors la discussion doit porter sur les preuves, et non sur son prestige. C'est exactement ce que demande le Coran : examiner, réfléchir, comparer. La seule chose que l'on refuse, c'est de remplacer cet examen par un argument d'autorité, dans un sens comme dans l'autre.")),
"Pourquoi un grand savant peut ne pas croire": dev([
  "Ce tableau donne quatre raisons, et chacune s'appuie sur une source. **Le savoir est spécialisé** : on peut être un expert de la cellule ou des galaxies et n'avoir jamais réfléchi sérieusement à la question de Dieu. Ibn Kathīr décrit ces gens « habiles et intelligents pour la vie d'ici-bas, inattentifs à l'au-delà ». Al-Hasan al-Basrī donnait l'image de celui qui devine le poids d'une pièce en la posant sur son ongle, sans savoir bien prier.",
  "**L'orgueil** : se soumettre est difficile pour qui a l'habitude de maîtriser. **Le coût social** : dans certains milieux, croire peut coûter une réputation, une carrière, des amitiés. Héraclius, empereur instruit, reconnut les signes d'un prophète, puis recula devant la colère de ses patriarches. **L'illusion de suffisance** : Ibn Masʿūd disait que l'illusion sur soi suffit comme ignorance. On peut tout savoir et se croire au-dessus de la question.",
  "Aucune de ces raisons ne touche **la vérité des preuves**. Elles touchent toutes **la disposition de celui qui les reçoit**. Voilà pourquoi le nombre de savants croyants ou incroyants ne tranche rien."]),
"Du signe à l’adhésion": dev([
  "Ce schéma, déjà présent sur le site, dit la même chose que le précédent sous une autre forme. **Le signe** : l'ordre du monde, la contingence des choses, la parole révélée. **La perception** : l'intelligence saisit le signe et en reconnaît la portée. **Le consentement** : l'acte libre par lequel on accepte ce que l'on a compris. **La foi vécue** : la reconnaissance devient l'orientation de toute la vie.",
  "La légende du schéma est essentielle : l'objection « les savants ne croient pas » suppose que la chaîne s'arrête à la deuxième étape, comme si comprendre suffisait. Or c'est **à la troisième étape que tout se joue**. Entre comprendre et consentir, il y a la liberté humaine, et cette liberté peut dire non à ce qu'elle a compris."]),
"Deux sortes de savoir": dev([
  "Ce tableau oppose deux savoirs qui ne se font pas concurrence. **Le savoir de la surface**, celui que décrit le verset 30:7, porte sur le fonctionnement des choses : comment, combien, à quelle vitesse. Il utilise la mesure et le calcul. **Le savoir de la finalité** porte sur le pourquoi : pourquoi il y a quelque chose plutôt que rien, vers où va ma vie. Il utilise la raison, la révélation et l'examen de soi.",
  "La ligne la plus importante est la dernière : **le risque**. Le savoir de la surface court un risque particulier, celui de croire que ce qui se mesure est tout ce qui existe. C'est une erreur de méthode, car l'instrument de mesure ne peut pas, par définition, mesurer ce qui n'est pas matériel. Le savoir de la finalité, lui, ne risque rien tant qu'il reste fidèle aux preuves."],
  Q("La science ne finira-t-elle pas par répondre aussi à la question du pourquoi ?",
    "La science répond à des questions de fonctionnement avec une puissance admirable. Mais même une connaissance complète de toutes les lois de la nature laisserait entière la question : pourquoi ces lois existent-elles, et pourquoi sont-elles ainsi réglées ? Cette question n'est pas en retard sur la science ; elle est d'un autre ordre.")),
"Deux définitions du savant": dev([
  "Ce tableau ne méprise pas la définition moderne : un physicien qui nie Dieu reste un grand physicien, et le tableau le dit explicitement. Mais il montre que le Coran **ajoute un critère** : un savoir qui ne produit aucune crainte révérencielle devant l'Auteur du monde est un savoir incomplet. Pour Ibn ʿAbbās, les savants du verset 35:28 sont « ceux qui savent qu'Allāh est capable de toute chose ».",
  "C'est pourquoi les anciens disaient : « le savant, c'est celui qui craint Allāh » (Mujāhid), et même « celui qui ne craint pas Allāh n'est pas un savant » (al-Rabīʿ ibn Anas). Ils ne parlaient pas de compétence technique, mais de **savoir accompli**, celui qui va jusqu'au bout de ce qu'il découvre."]),
"Ce que disent les savants, en un coup d'œil": dev([
  "Ce tableau résume la convergence des commentateurs : Ibn ʿAbbās, al-Hasan, Ibn Masʿūd, Mujāhid, al-Qurtubī, Ibn Kathīr. Tous distinguent **le savoir qui reste à la surface** et **le savoir qui mène à Dieu**, et tous voient dans l'orgueil et l'illusion sur soi l'obstacle principal. Aucun d'eux ne dit que les négateurs sont tous des ignorants ; tous disent que **l'intelligence ne suffit pas**."])
}}

# ---------------------------------------------------------------- Cosmos
ADD["Dieu regarde-t-Il l'homme, si petit dans l'immensité du cosmos ?"] = {"after": {
"Les deux erreurs de l'objection": dev([
  "Ce tableau isole les deux présupposés cachés de l'objection. **Premier présupposé, sur la valeur** : plus une chose est grande, plus elle compte. Mais nous ne le pensons jamais dans la vie réelle : personne ne dit qu'une montagne vaut plus qu'un enfant, ni qu'un éléphant vaut plus qu'un homme. La valeur vient de **la conscience, de la liberté et de la responsabilité**, et c'est exactement ce que le Coran honore dans le verset 17:70.",
  "**Second présupposé, sur l'attention** : Dieu devrait choisir entre les galaxies et l'homme, comme un gardien qui ne peut surveiller deux portes à la fois. Mais c'est projeter sur Dieu une limite humaine. Le Coran dit : « pas une feuille ne tombe sans qu'Il le sache » (6:59). Une science qui embrasse chaque feuille de chaque arbre de chaque planète **n'a pas besoin de choisir**.",
  "Les deux dernières lignes renversent la conclusion : l'univers n'est pas l'arène où l'homme se perd, il est **mis à son service** (45:13). Et son immensité devient **la mesure de la générosité** de Celui qui l'a fait pour nous."],
  Q("Mais s'il existe d'autres êtres intelligents dans l'univers, l'homme n'est plus le centre ?",
    "Le Coran ne dit pas que l'homme est la seule créature honorée ; il parle des anges, des djinns, et dit que Dieu crée « ce que vous ne savez pas » (16:8). L'existence éventuelle d'autres créatures ne retire rien à l'honneur fait à l'homme : un père qui a plusieurs enfants n'aime pas moins chacun d'eux.")),
"Comment le Coran renverse la perspective": dev([
  "Ce schéma suit la logique du Coran en quatre temps. **L'univers est immense** : le Coran ne le cache pas, il invite au contraire à lever les yeux. **Il est mis au service** : Ibn ʿĀshūr détaille ce service, le soleil pour la lumière, la pluie pour boire, les étoiles pour se guider. **L'homme est honoré** : al-Qurtubī précise qu'il s'agit d'une noblesse qui écarte l'imperfection, pas d'une richesse matérielle. **Il est connu jusque dans le détail** : rien n'est trop petit pour la science de Dieu.",
  "Lus dans cet ordre, ces quatre versets transforment le vertige en gratitude. Ce n'est plus « que suis-je face à tout cela ? », mais « **tout cela a été préparé, et je suis connu au milieu de tout cela** »."]),
"Deux manières de regarder": dev([
  "Ce schéma, présent sur le site, compare deux regards. **Le regard d'une créature** est limité : il se partage, et plus l'objet est vaste, moins le détail est vu. Pour nous, l'attention est une ressource rare. **La science du Créateur** est une, sans effort ni succession : le tout et le détail sont connus du même savoir, au même instant.",
  "D'où les deux conséquences du schéma. **Pour le cosmos** : son immensité n'est pas une charge pour Dieu, elle est un signe parmi Ses signes. **Pour l'homme** : sa petitesse n'est pas un oubli, elle est **le lieu même où la sollicitude se manifeste**. La légende le résume : l'objection naît d'une projection, appliquer à Dieu la loi de l'attention humaine."]),
"Ce que disent les savants, en un coup d'œil": dev([
  "Les commentateurs convergent : l'homme est honoré non par sa taille mais par la noblesse que Dieu lui a donnée (al-Qurtubī) ; le cosmos est créé pour son intérêt et constitue à la fois un bienfait et une preuve (al-Qurtubī, Ibn ʿĀshūr) ; et la science divine n'est limitée par aucune échelle. Aucun ne voit dans l'immensité du ciel une raison de se sentir oublié ; tous y voient une raison de remercier."]),
"Ce qui fait la valeur d'un être, selon le Coran": dev([
  "Ce schéma pose quatre critères. **Non la masse** : le soleil, des milliers de fois plus massif que la terre, est décrit par le Coran comme courant vers un terme fixé, en obéissance. Sa grandeur ne lui donne aucune liberté. **Mais la conscience** : l'homme sait qu'il existe et qu'il mourra ; c'est une profondeur que les étoiles n'ont pas. **Et la charge** : le dépôt (amāna) que les cieux, la terre et les montagnes ont refusé de porter, l'homme l'a accepté (33:72).",
  "D'où la conclusion : **le regard divin**. On ne parle pas, on n'envoie pas de messagers, on ne promet pas de récompense à ce que l'on néglige. Le simple fait que Dieu s'adresse à l'homme prouve qu'Il le regarde."]),
"Le cosmos selon le Coran : trois fonctions": dev([
  "Ce schéma résume la lecture d'Ibn ʿĀshūr du verset 45:13. Chaque élément du cosmos a **trois fonctions à la fois** : il est **un bienfait** (la lumière du soleil me fait vivre), **un signe** (cette lumière prouve Celui qui l'envoie), et **un appel** à réfléchir puis à remercier.",
  "Le verset se termine par « des signes pour des gens qui **réfléchissent** », et non « pour des gens qui mesurent ». La mesure est indispensable, mais elle s'arrête au comment ; la réflexion va jusqu'au pourquoi. Le croyant n'a pas besoin de choisir entre l'astronome et le contemplatif : il peut être les deux."])
}}

# ---------------------------------------------------------------- Dieu des Arabes
ADD["Allāh est-il « un dieu des Arabes » ?"] = {"after": {
"Du mot à la réalité qu'il désigne": dev([
  "Ce schéma suit le chemin qui va d'un mot à ce qu'il désigne. **Un mot arabe** : « Allāh » appartient à la langue arabe, comme « Dieu » au français. **Une réalité universelle** : ce mot désigne « le Seigneur des mondes », c'est-à-dire, selon Qatāda, tout ce qui existe en dehors de Lui. **Un message adressé à tous** : le Coran se présente comme un avertissement « pour les mondes » (25:1). **Un appel à tous les peuples** : le Prophète ﷺ écrit à l'empereur de Byzance pour l'inviter à « une parole commune ».",
  "À chaque étape, on s'éloigne de l'idée d'un dieu local. Un dieu tribal ne se présenterait pas comme le Seigneur de tout ce qui existe, et son prophète n'écrirait pas aux empereurs étrangers."],
  Q("Pourquoi alors le Coran est-il en arabe, si son message est universel ?",
    "Parce qu'un message doit bien être révélé dans une langue, et que le premier peuple à le recevoir devait le comprendre pour le transmettre. Le Coran dit : « Nous n'avons envoyé de messager que dans la langue de son peuple, afin qu'il leur explique clairement » (14:4). La langue est le point de départ de la transmission, pas la limite de son destinataire.")),
"Arabe par la langue, universel par le contenu": dev([
  "Ce tableau sépare ligne par ligne ce qui relève de la langue et ce qui relève du contenu. **Le nom** est arabe, mais il désigne le même Créateur qu'on appelle « Dieu » ou « God ». **Le Livre** est en arabe clair, mais il s'adresse aux mondes. **Le Messager** est né à La Mecque, mais il est envoyé « à vous tous » (7:158). **La croyance** est formulée en arabe, mais c'est le même tawhīd que celui d'Abraham, de Moïse et de Jésus.",
  "Le schéma « ilāh / Allāh » présent plus bas sur la page ajoute un fait historique : **les chrétiens arabes appellent Dieu « Allāh »** dans leurs bibles depuis les premiers siècles, et le mot a la même racine sémitique que l'hébreu Eloah et l'araméen Alāhā. Le mot n'est donc ni ethnique ni confessionnel : c'est le mot arabe pour dire Dieu."]),
"ilāh / Allāh": dev([
  "Ce schéma résume les faits de langue. **« Ilāh »** est un nom commun : une divinité, tout ce qui est adoré. **« Allāh »**, contraction de « al-ilāh », est la Divinité par excellence, sans féminin ni pluriel. **L'usage arabe chrétien** : les bibles arabes traduisent le grec Theos et l'hébreu Elohim par « Allāh ». **La parenté sémitique** : Eloah en hébreu, Alāhā en araméen, la langue de Jésus.",
  "La conclusion de la légende s'impose : si les juifs et les chrétiens arabophones disent eux aussi « Allāh », alors ce mot ne peut pas désigner un dieu réservé aux musulmans arabes. Ce que l'islam affirme de particulier, ce n'est pas un autre Dieu, c'est **l'unicité stricte** de ce Dieu-là."]),
"Ce que disent les savants, en un coup d'œil": dev([
  "Tous les commentateurs cités définissent « les mondes » de la manière la plus large possible : tout ce qui existe en dehors de Dieu (Qatāda, Ibn Kathīr), ou au moins les djinns et les humains à qui le message est adressé (Ibn ʿAbbās). Aucun n'imagine une seconde que le Seigneur des mondes puisse être le dieu d'un seul peuple."]),
"Confondre la langue et le destinataire": dev([
  "Ce tableau reprend l'erreur de base de l'objection, qui confond **la langue d'un message** avec **son destinataire**. On pourrait faire la même confusion avec n'importe quel texte : une déclaration écrite en anglais n'est pas réservée aux Anglais, et un traité de mathématiques rédigé en allemand vaut pour le monde entier.",
  "La dernière ligne rappelle que la croyance proclamée par le Coran n'est pas présentée comme une nouveauté arabe, mais comme **le retour à la religion d'Abraham**, que juifs et chrétiens revendiquent aussi. Le Coran dit : « Notre Dieu et votre Dieu est le même » (29:46)."]),
"Ce que montre la lettre": dev([
  "Ce tableau confronte l'hypothèse d'un dieu des Arabes avec ce que fait réellement le Prophète ﷺ. **Le destinataire** : il écrit à Héraclius, empereur des Romains, chrétien grec. **Le contenu** : il ne lui propose pas d'adopter un dieu étranger, mais de revenir à « une parole commune » : n'adorer qu'un seul Dieu. **La promesse** : « embrasse l'islam, tu seras sauvé », un salut pour lui personnellement, pas une alliance politique.",
  "On sait par les Sahīh qu'il écrivit aussi au roi de Perse et à d'autres souverains. **Un prophète qui écrit aux empires voisins dans la première décennie de sa mission** n'annonce pas un culte national : il annonce un message universel."])
}}

# ---------------------------------------------------------------- Vision
ADD["Peut-on voir Dieu de ces yeux-ci ?"] = {"after": {
"Pourquoi Dieu ne se montre pas maintenant": dev([
  "Ce schéma répond à la question « pourquoi Dieu ne se montre-t-Il pas ? » par cinq raisons qui s'enchaînent. **Nos yeux ne le supporteraient pas** : quand Dieu s'est manifesté à la montagne, elle s'est effondrée, et Moïse est tombé foudroyé (7:143). Ce n'est pas un défaut de Dieu, c'est la faiblesse de notre constitution actuelle.",
  "**La vie est une épreuve** : le Coran décrit les croyants comme « ceux qui croient à l'invisible » (2:3). Si l'invisible devenait visible, cette qualité n'aurait plus de sens. **Le voile protège la liberté** : une évidence écrasante, comme le soleil à midi, ne laisserait plus de place au choix. Personne n'a de mérite à croire que le soleil existe.",
  "**La vision est la récompense** : ceux qui ont cru sans voir verront ; c'est le sommet du Paradis. **Le voile devient châtiment** pour ceux qui ont refusé : « ce jour-là, ils seront voilés à leur Seigneur » (83:15). Le même voile qui, ici-bas, protégeait la liberté, devient dans l'au-delà la conséquence du refus."],
  Q("Si Dieu se montrait, tout le monde croirait. N'est-ce pas ce qu'Il veut ?",
    "Dieu veut une foi libre, pas une soumission arrachée par l'évidence. Le Coran rapporte que les négateurs, même devant le châtiment, ne croiraient pas sincèrement : « s'ils étaient renvoyés, ils recommenceraient » (6:28). Une vision forcée produirait une contrainte, pas une conversion du cœur."),
  Q("Pourquoi les croyants mériteraient-ils de voir Dieu plus que les autres ?",
    "Parce que c'est exactement ce qu'ils ont cherché. L'imam Mālik l'a dit : puisqu'Il a voilé Ses ennemis, Il Se manifestera à Ses alliés. Celui qui a passé sa vie à aimer Dieu sans Le voir reçoit ce qu'il désirait ; celui qui L'a refusé ne reçoit pas ce qu'il refusait.")),
"Ici-bas et dans l'au-delà": dev([
  "Ce tableau oppose les deux demeures. **Ici-bas**, personne ne voit Dieu, pas même un prophète : interrogé par Abū Dharr, le Prophète ﷺ répondit « Lumière : comment pourrais-je Le voir ? ». **Dans l'au-delà**, les croyants Le verront comme on voit la lune, clairement et sans bousculade, selon le hadith de Jarīr.",
  "**Le rôle du voile** change d'une demeure à l'autre : ici, il laisse la place à la foi ; là-bas, il devient une privation pour ceux qui ont refusé. **Ce que l'on fait** : ici, on adore « comme si on Le voyait », selon la définition de l'excellence (ihsān) dans le hadith de Gabriel ; là-bas, on Le voit, et c'est, selon le hadith de Suhayb, le plus aimé de tous les dons."]),
"La vision : deux demeures, deux régimes": dev([
  "Ce schéma, déjà présent sur le site, précise ce qui est affirmé et ce qui est nié. **Ici-bas, la vision est impossible** : non par défaut de Dieu, mais par faiblesse de la créature. **Dans l'au-delà, elle est réelle** : affirmée par le Coran (75:23) et par de nombreux hadiths rigoureux. **Ce qui est nié dans tous les cas** : le fait de cerner, de délimiter, de situer. **Ce qui est affirmé** : une vision réelle, sans modalité connue de nous.",
  "La légende désigne la source de toutes les confusions : projeter sur la vision de l'au-delà **les conditions physiques de la vision d'ici-bas** (la distance, la direction, la lumière qui frappe l'œil). Dans l'au-delà, nos corps et nos yeux seront autres, et la vision sera donnée par Dieu selon un mode que nous ne connaissons pas encore."],
  Q("Voir sans cerner, est-ce possible ?",
    "Même dans notre monde, nous voyons des choses que nous ne cernons pas : nous voyons le ciel sans en voir les limites, nous voyons la mer sans en embrasser toute l'étendue. Le Coran dit que « les regards ne L'atteignent pas » (6:103) : on peut voir réellement sans encercler ce qu'on voit.")),
"Ce que disent les savants, en un coup d'œil": dev([
  "Les savants cités forment un ensemble remarquablement cohérent. Mālik et al-Shāfiʿī tirent du verset du voile (83:15) la preuve de la vision pour les croyants ; al-Zajjāj ajoute que sinon le verset ne menacerait de rien ; al-Qurtubī affirme que c'est l'avis de la grande majorité ; Ibn Kathīr rapporte les hadiths authentiques. Et ʿĀʾisha comme Abū Dharr rappellent que **ici-bas**, même le Prophète ﷺ ne L'a pas vu de ses yeux."]),
"La vision : ce qui est affirmé, ce qui est nié": dev([
  "Ce schéma met en ordre quatre versets. **Ici-bas**, « tu ne Me verras pas » (7:143). **Dans l'au-delà**, « vers leur Seigneur elles regarderont » (75:23). **Sans cerner**, « les regards ne L'atteignent pas » (6:103). **La récompense suprême**, « le surcroît » promis aux bienfaisants (10:26), que les commentateurs ont expliqué par la vision.",
  "Ces versets ne se contredisent pas : ils parlent de **deux moments** (ici-bas et l'au-delà) et de **deux choses** (voir et cerner). Une fois ces deux distinctions faites, tout s'éclaire."]),
"Le débat des Compagnons sur l'Ascension": dev([
  "Ce tableau montre que même les Compagnons ont débattu de cette question, et qu'ils l'ont fait avec respect. **ʿĀʾisha** nie que le Prophète ﷺ ait vu son Seigneur lors de l'Ascension, en s'appuyant sur deux versets et sur ce que le Prophète ﷺ lui avait dit lui-même : c'était Gabriel. **D'autres transmissions**, attribuées à Ibn ʿAbbās, parlent d'une vision par le cœur.",
  "La dernière ligne est la plus importante : **aucun Compagnon n'a dit que le Prophète ﷺ L'avait vu de ses yeux comme on voit une créature**. Le débat porte sur une vision du cœur, pas sur une vision physique ordinaire. Et la parole authentique du Prophète ﷺ rapportée par Muslim, « Lumière : comment pourrais-je Le voir ? », montre l'humilité de celui qui était pourtant le plus proche de Dieu."],
  Q("Si les Compagnons ne sont pas d'accord, que dois-je croire ?",
    "Ce qui est certain, c'est que personne ne voit Dieu ici-bas avec ces yeux, et que les croyants Le verront dans l'au-delà. La question précise de l'Ascension est un cas particulier, discuté par les plus grands, et elle ne remet pas en cause ces deux certitudes. On peut garder l'humilité de dire : Allāh sait mieux."))
}}

# ---------------------------------------------------------------- Dieu était
ADD["Dieu était, et rien n'était avec Lui : le temps commence-t-il avec la création ?"] = {"after": {
"Deux manières de se représenter le commencement": dev([
  "Ce tableau compare deux images du commencement. **La représentation fautive** imagine le temps comme une scène vide, qui existait déjà, sur laquelle Dieu attendait avant de créer. C'est une image naturelle, parce que nous vivons dans le temps et avons du mal à penser hors de lui. **La représentation juste** dit que le temps est lui-même une créature : il commence avec le monde dont il mesure le changement.",
  "Les conséquences sont décisives. **Dieu** n'est pas un être dans le temps ; Il est « le Premier, rien n'est avant Toi ». **La question « pourquoi pas plus tôt ? »** perd son sens, car il n'y avait pas de « plus tôt ». **La raison** elle-même, comme l'a montré al-Bayhaqī, refuse une chaîne infinie de causes sans début, et exige un Premier sans commencement."],
  Q("Comment imaginer quelque chose hors du temps ? C'est impensable.",
    "Impensable en images, oui ; mais pas en raisonnement. Nous savons raisonner sur des choses que nous ne pouvons pas imaginer : un nombre infini, un espace à plus de trois dimensions. L'impossibilité d'imaginer n'est pas une impossibilité d'exister. Et c'est exactement ce que dit « rien ne Lui ressemble » : notre imagination n'a pas de prise sur Lui."),
  Q("Que faisait Dieu avant la création ?",
    "La question suppose un « avant » temporel. Mais « avant » la création, il n'y avait pas de temps, donc pas de durée pendant laquelle Dieu aurait été inactif. Dieu n'attendait pas ; Il était, avec Ses attributs parfaits, et Il a créé quand Il a voulu, le temps compris.")),
"Ce que dit le hadith, étape par étape": dev([
  "Ce schéma suit l'ordre du hadith de ʿImrān ibn Husayn. **Allāh était** : seul, sans rien avec Lui. **Son Trône était sur l'eau** : ce sont les premières créatures mentionnées, avant les cieux et la terre, comme le dit aussi le verset 11:7. **Il écrivit toute chose** : le décret de toute la création, avant sa réalisation. **Il créa les cieux et la terre** : et avec eux, les jours et les nuits, c'est-à-dire le temps que nous mesurons.",
  "Le hadith répond donc à la question des gens du Yémen avec une précision étonnante : il ne décrit pas un temps vide précédant le monde, mais **une succession de créations** dont la première condition est l'existence seule de Dieu."]),
"Ce qui a un commencement, ce qui n’en a pas": dev([
  "Ce schéma, déjà présent sur le site, pose les deux catégories de la théologie. **Le qadīm**, ce qui est sans commencement ni fin ni cause : il n'y en a qu'un, Allāh avec Ses attributs. **Le hādith**, ce qui advient : la matière, le mouvement, l'espace, et le temps lui-même. **Le temps** est la mesure du mouvement des créatures ; s'il n'y a pas de mouvement, il n'y a pas de temps.",
  "La dernière case nomme **l'erreur commune** : se représenter un temps vide qui « attendait » la création. La légende résume tout : le temps n'est pas le contenant de la création, il est l'une des choses créées."]),
"Ce que disent les savants, en un coup d'œil": dev([
  "Les sources réunies ici forment un raisonnement complet : le hadith pose le fait (Dieu était seul), l'invocation prophétique en donne les noms (le Premier, le Dernier), al-Qurtubī souligne que cette explication prophétique suffit, et al-Bayhaqī montre que la raison aboutit au même endroit. **Révélation et raison se rejoignent.**"]),
"Les quatre noms, expliqués par le Prophète ﷺ": dev([
  "Ce schéma reprend l'invocation rapportée par Muslim, où le Prophète ﷺ explique lui-même quatre noms. **Le Premier** : rien n'est avant Lui, Il n'a pas de commencement. **Le Dernier** : rien n'est après Lui, Il n'a pas de fin. **L'Apparent** : rien n'est au-dessus de Lui ; al-Qurtubī explique « le Dominant ». **Le Caché** : rien n'est en deçà de Lui ; al-Qurtubī explique « Celui qui sait tout ».",
  "Ces quatre noms encadrent toute l'existence : avant, après, au-dessus, en dedans. Il n'y a **aucun espace** où l'on pourrait être hors de Sa présence ou de Sa science."]),
"L'argument d'al-Bayhaqī, étape par étape": dev([
  "Ce schéma reprend un raisonnement classique, que je résume avec mes mots pour qu'il soit accessible. **Tout corps change** : il bouge ou s'arrête, se rassemble ou se sépare ; on ne trouve jamais un corps qui serait absolument sans aucun état changeant. **Ces états commencent et finissent** : un mouvement remplace un repos ; ce qui peut disparaître ne peut pas être éternel.",
  "**Ce qui dépend du changeant commence aussi** : si un corps n'existe jamais sans des états qui commencent, il a lui-même commencé. **Ce qui commence a une cause** : sinon, rien n'explique qu'il existe plutôt que pas. **Cette cause n'a pas commencé** : sinon, il faudrait remonter sans fin, et une chaîne infinie de causes qui commencent n'explique jamais pourquoi il y a quelque chose.",
  "Le raisonnement ne prouve pas tout ce que la révélation enseigne de Dieu ; il prouve **qu'il faut un Premier sans commencement**. Et c'est exactement ce que dit le hadith : « Allāh était, et rien d'autre que Lui n'était »."],
  Q("Et si l'univers lui-même était éternel ?",
    "C'est précisément ce que l'argument conteste : un univers fait de corps qui changent sans cesse ne peut pas être sans commencement, selon al-Bayhaqī. Il est intéressant de noter que la cosmologie moderne, de son côté, parle d'un commencement de l'univers observable. Le croyant n'a pas besoin de cette convergence pour croire, mais il peut la remarquer."))
}}

# ---------------------------------------------------------------- Muwāfāt
ADD["Nul n'a la garantie de mourir croyant : la notion de muwāfāt"] = {"after": {
"La muwāfāt vue sous ses deux faces": dev([
  "Ce tableau montre qu'une même règle protège deux personnes opposées. **Pour celui qui se croit sauvé**, le danger est l'orgueil, la sécurité illusoire, l'hypocrisie cachée. La muwāfāt lui dit : « les œuvres ne valent que par leur fin », rien n'est acquis. Elle produit chez lui la vigilance et la sincérité.",
  "**Pour celui qui se croit perdu**, le danger est le désespoir, l'abandon de tout effort. La muwāfāt lui dit le contraire : al-Muhallab explique qu'une parole de vérité prononcée avant la mort efface la mécréance et ses œuvres. Elle produit chez lui l'espérance et le retour.",
  "La dernière ligne cite deux versets qui se répondent : « Ne fais pas dévier nos cœurs après nous avoir guidés » (3:8), la prière de celui qui a peur de perdre ; « Ne désespérez pas de la miséricorde d'Allāh » (39:53), l'appel à celui qui croit avoir tout perdu. **La même vérité, deux médicaments.**"],
  Q("N'est-ce pas injuste qu'un criminel se repente à la dernière minute et soit sauvé ?",
    "C'est la miséricorde de Dieu, et c'est aussi Sa justice : le repentir sincère n'est pas une formule magique, c'est un retournement réel du cœur. Et nul ne sait s'il aura le temps de se repentir. Celui qui compte sur un repentir tardif joue avec sa vie ; celui qui se repent réellement, même tard, a changé. La porte est ouverte, mais nul ne connaît l'heure où elle se ferme.")),
"Pourquoi la fin n'est pas une loterie": dev([
  "Ce schéma répond à la peur principale : « et si je finissais mal par hasard ? ». **Ce qu'on cultive en secret** : la sincérité ou l'ostentation, la prière cachée ou le péché caché. **Ce qui devient habitude** : ce qu'on répète finit par devenir le fond de l'âme. **Ce qui remonte à la fin** : quand les forces s'en vont, quand on ne peut plus jouer de rôle, il ne reste que ce fond.",
  "Le dernier nœud est le plus rassurant : **la fermeté vient de Dieu**. « Allāh affermit ceux qui ont cru par la parole ferme, ici-bas et dans l'au-delà » (14:27). Celui qui a cultivé sa foi en secret n'est pas laissé seul au moment de la fin.",
  "La fin n'est donc pas un tirage au sort : c'est **la vérité qui se révèle**. Les savants ont remarqué que ceux qui finissent mal après une vie apparemment pieuse sont souvent ceux dont l'intérieur ne correspondait pas à l'extérieur. Le remède n'est pas la peur, mais la sincérité."]),
"Le poids du terme": dev([
  "Ce schéma, déjà présent sur le site, explique le mot lui-même. **L'état présent** : à chaque instant, on est dans un certain état de foi ou d'incroyance. **Le parcours** : cet état peut se retourner, dans un sens ou dans l'autre, jusqu'au dernier souffle. **La muwāfāt** : c'est l'état effectif au moment où l'âme quitte le corps. **Le sort dernier** est fondé sur ce terme, connu de Dieu de toute éternité.",
  "La légende en tire trois règles de conduite : **on espère sans se croire sauvé, on craint sans désespérer, et on ne juge personne comme définitivement perdu de son vivant**. Cette troisième règle est souvent oubliée : la muwāfāt interdit de condamner quiconque tant qu'il respire."]),
"Ce que disent les savants, en un coup d'œil": dev([
  "Ce tableau réunit les hadiths fondateurs et leurs commentateurs. Ils disent tous la même chose : la fin décide (hadiths d'Ibn Masʿūd et de Sahl), cette règle est cohérente avec toute la loi (al-Muhallab), et elle doit maintenir la crainte même chez les plus pieux (al-Qurtubī, al-Sarī). Aucun n'en tire une raison de désespérer ; tous en tirent une raison de veiller."]),
"Comment le croyant vit avec la muwāfāt": dev([
  "Ce cycle montre comment la muwāfāt devient une manière de vivre plutôt qu'une angoisse. **Crainte** : je ne me fie pas à mon passé. **Espérance** : je ne désespère de personne, pas même de moi. **Invocation** : je demande la fermeté, car c'est Lui qui affermit. **Constance** : je fais de chaque jour une fin possible, et je la soigne.",
  "Au centre du cycle : **la bonne fin**. On ne l'obtient pas en y pensant avec peur, mais en vivant chaque jour comme s'il pouvait être le dernier, non par angoisse, mais par soin."]),
"Le walī peut-il se savoir walī ?": dev([
  "Ce tableau présente un débat subtil rapporté par al-Qurtubī. **Premier avis** : non, car le walī est celui dont la fin est heureuse, et la fin est voilée. Se croire walī, c'est risquer de perdre la crainte. Al-Sarī disait que même si les oiseaux de chaque arbre te saluaient « ô allié d'Allāh », il faudrait craindre une ruse.",
  "**Second avis** : c'est possible, puisque le Prophète ﷺ a annoncé le Paradis à dix Compagnons. Mais ce savoir ne leur a pas fait perdre leur crainte ; au contraire, ils sont devenus plus révérencieux. La dernière ligne réconcilie les deux avis : **la crainte doit durer jusqu'à ce que les anges descendent dire « ne craignez pas »** (41:30), c'est-à-dire jusqu'à la mort."],
  Q("Alors je ne peux jamais être en paix ?",
    "La paix du croyant n'est pas l'absence de crainte, c'est la confiance qui accompagne la crainte. Les Compagnons vivaient dans une grande sérénité tout en craignant Dieu. La crainte qui pousse à agir n'empêche pas la paix ; seule la crainte qui paralyse est contraire à la foi."))
}}

# ---------------------------------------------------------------- Amour
ADD["L'amour de Dieu : ce qui l'attire, ce qui l'éloigne"] = {"after": {
"Miséricorde et amour": dev([
  "Ce tableau distingue deux choses qu'on confond souvent. **La miséricorde (rahma)** est donnée à toute créature, croyante ou non : la vie, la santé, la pluie, la nourriture, et même le délai qui permet de revenir. Elle ne demande rien en retour : c'est un don. **L'amour (mahabba)**, au sens de la proximité et de l'élection, répond à un mouvement du serviteur : il est réservé à ceux qui s'approchent.",
  "Cette distinction répond à l'objection d'un amour « conditionnel ». Dieu ne retire Sa miséricorde à personne tant qu'il vit ; mais Il ne force personne à entrer dans Sa proximité. C'est le même principe que dans la page sur le châtiment : **Dieu ne contraint pas une relation**. Il l'offre, et Il l'honore quand elle est acceptée."],
  Q("Un amour qui dépend de ce qu'on fait n'est-il pas un amour intéressé ?",
    "Un amour intéressé cherche son propre profit. Or Dieu n'a besoin de rien ; ce que le serviteur fait ne Lui apporte rien. Son amour n'est pas un salaire payé pour un service rendu ; c'est une proximité qui s'ouvre à celui qui s'ouvre. Comme une lumière qui éclaire celui qui ouvre ses volets : elle ne change pas, c'est lui qui se met dans sa direction.")),
"Le cercle de l'amour divin": dev([
  "Ce cycle montre l'ordre réel de l'amour. **Dieu aime d'abord** : dans le verset 5:54, « Il les aime » vient avant « ils L'aiment ». Notre amour pour Lui n'est pas le point de départ, c'est une réponse. **Le serviteur répond** : par les obligations d'abord, puis les actes surérogatoires. **Dieu rapproche** : « jusqu'à ce que Je l'aime », puis Il devient « son ouïe, sa vue, sa main », c'est-à-dire qu'Il guide ce qu'il écoute, regarde et fait. **Le ciel et la terre l'aiment** : Gabriel, les anges, puis l'accueil favorable parmi les gens.",
  "Le cercle se referme : plus le serviteur est aimé, plus il aime ; plus il aime, plus il s'approche."]),
"Ceux qu’Il aime, ceux qu’Il n’aime pas": dev([
  "Ce schéma, déjà présent sur le site, montre que le Coran ne parle pas d'un amour vague : il l'attache à des qualités précises. **Les pieux** (la vigilance intérieure), **les bienfaisants** (faire le bien au-delà du dû), **les repentants et les purs** (la faute n'exclut pas, c'est l'installation dans la faute qui exclut), **les patients et les confiants**. Et à l'inverse, **les injustes**, **les orgueilleux**, **les corrupteurs**.",
  "La troisième case mérite une attention particulière : **Dieu aime les repentants**. Cela signifie que celui qui a péché et revient est aimé **à cause de son retour**, pas malgré lui. La porte de l'amour n'est pas fermée par la faute, mais par le refus de revenir."]),
"Ce que disent les savants, en un coup d'œil": dev([
  "Les savants réunis ici convergent sur un point : l'amour de Dieu se prouve par les actes, non par les déclarations. Ibn Kathīr et al-Hasan le tirent du verset 3:31 ; al-Azharī définit l'amour du serviteur comme l'obéissance ; Ibn ʿAbd al-Barr rapporte les hadiths qui montrent comment cet amour descend et s'attire ; et al-Dārānī rappelle que l'amour en Dieu entre frères se voit dans les visites et le partage."]),
"Le chemin de l'amour divin, du ciel à la terre": dev([
  "Ce schéma suit l'ordre du hadith du Muwatta. **Allāh aime** : tout commence par Lui. **Gabriel aime** : le plus noble des anges reçoit l'annonce. **Le ciel aime** : l'amour se diffuse dans le monde invisible. **La terre accueille** : l'affection sincère des gens n'est que l'écho de ce qui a été décidé là-haut.",
  "Ce hadith a une conséquence pratique : **ne cherche pas d'abord l'amour des gens**. Cherche l'amour de Dieu, et l'amour sincère des gens viendra par surcroît. Celui qui cherche d'abord à plaire aux gens finit souvent par perdre les deux."],
  Q("Mais il y a des gens pieux qui sont détestés, et des gens mauvais qui sont aimés ?",
    "Le hadith parle de « l'accueil favorable » (al-qabūl), qui n'est pas la popularité. Un homme pieux peut être détesté par certains et pourtant laisser une trace de bien durable dans le cœur des gens de bien. Et la popularité d'un homme mauvais est souvent fragile. Le hadith décrit une tendance profonde, pas un sondage d'opinion.")),
"Les quatre portes du hadith de Muʿādh": dev([
  "Ce schéma détaille les quatre portes par lesquelles l'amour divin devient acquis. **S'aimer en Dieu** : aimer quelqu'un pour sa foi et son bien, non pour un intérêt. **S'asseoir ensemble en Dieu** : se réunir pour apprendre et s'encourager. **Se visiter en Dieu** : aller voir son frère sans autre motif que lui. **Se donner en Dieu** : selon Ibn ʿAbd al-Barr, que chacun donne de ses biens à son frère quand il en a besoin.",
  "On remarque que **les quatre portes passent par les autres**. L'amour de Dieu ne s'obtient pas seulement dans la solitude de la prière ; il s'obtient aussi dans la fraternité, les visites, le partage. Al-Dārānī l'a dit : on n'est pas frères en Dieu tant qu'on ne se visite pas et qu'on ne se donne pas l'un à l'autre."])
}}
